#pragma once
void tests06(const std::string&root){
 test("getMany preserves order, duplicates, empty/missing values and bounds",[&]{Store db(root+"/many",true);db.commit({{"a","one",ANY,false},{"b","",ANY,false}});auto v=db.getMany({"b","missing","a","a"});require(v.size()==4&&v[0].found&&v[0].value.empty()&&!v[1].found&&v[2].value=="one"&&v[2].version==v[3].version,"many values");require(db.getMany({}).empty(),"empty many");expect_error([&]{db.getMany(std::vector<std::string>(4097,"a"));});db.commit({{"large",std::string(16*1024*1024,'v'),ANY,false}});expect_error([&]{db.getMany({"large","large","large","large"});});});
 test("getMany observes one atomic batch across shards with concurrent writer",[&]{Store db(root+"/many-race",true);std::vector<Op> ops;std::vector<std::string> keys;for(int i=0;i<128;i++){keys.push_back(std::to_string(i));ops.push_back({keys.back(),"ok",ANY,false});}db.commit(ops);std::atomic<bool> stop{false},bad{false};std::thread t([&]{try{while(!stop){auto values=db.getMany(keys);for(auto&v:values)if(!v.found||v.version!=values[0].version)bad=true;}}catch(...){bad=true;}});for(int i=0;i<200;i++)db.commit(ops);stop=true;t.join();require(!bad,"mixed snapshot");});
 test("stream compaction beyond 64 MiB preserves versions and CAS after reopen",[&]{auto source=root+"/stream-source",dest=root+"/stream-copy";uint64_t version,tx;
  {Options o;o.reads=ReadMode::Pread;Store db(source,true,o);std::string value(1024*1024,'x');for(int i=0;i<80;i++)db.commit({{std::to_string(i),value,ANY,false}});version=db.get("20").version;db.commit({{"0","small",ANY,false},{"1","",ANY,true}});tx=db.txid();db.snapshot(dest,true);require(db.count()==79,"source changed");}
  {Store copy(dest);require(copy.count()==79&&copy.txid()==tx&&copy.get("20").version==version,"stream version");require(copy.get("20").value==std::string(1024*1024,'x'),"stream value");require(!copy.get("1").found&&copy.get("0").value=="small","stream deletes");copy.commit({{"20","updated",version,false}});copy.verify();}
  {Store copy(dest);require(copy.get("20").value=="updated","append after large checkpoint");}
  FD fd(::open(dest.c_str(),O_RDWR));unsigned char bad=255;write_at(fd.n,&bad,1,START+64+3000);auto size=file_size(fd.n);Options verify;verify.verifyOnOpen=true;expect_error([&]{Store copy(dest,false,verify);});require(file_size(fd.n)==size,"corrupt checkpoint modified");
 });
 test("streaming hash equals single-shot SHA across buffer boundaries",[&]{std::string bytes(2500000,'z');StreamHash h;for(size_t p=0;p<bytes.size();p+=777)h.update(bytes.data()+p,std::min<size_t>(777,bytes.size()-p));require(h.finish()==digest(bytes.data(),bytes.size()),"stream SHA mismatch");});
}
